import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{n,t as r}from"./ArticleLayout-Dv1nbDyM.js";var i,a,o=e((()=>{i=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurance temporaire : attestation immédiate, ce que vous recevez vraiment`,description:`Dès le paiement : Mémo Véhicule Assuré et carte internationale d'assurance par email. Valeur en contrôle routier et délais réels du FVA expliqués.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-temporaire-attestation-immediate`,datePublished:`2026-07-12`,dateModified:`2026-07-12`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Attestation immédiate : mémo et carte internationale`,item:`https://assutempo.fr/articles/assurance-temporaire-attestation-immediate`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Le Mémo Véhicule Assuré remplace-t-il la carte verte ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui. Depuis la suppression de la carte verte le 1er avril 2024, le Mémo Véhicule Assuré est le document remis par l'assureur à la souscription. Il ne remplace pas juridiquement le contrat, mais sert de preuve pratique tant que le Fichier des Véhicules Assurés (FVA) n'est pas encore à jour.`}},{"@type":`Question`,name:`Le FVA fait-il foi même sans présenter le Mémo ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, en priorité. Les forces de l'ordre consultent le FVA directement à la plaque d'immatriculation. Le Mémo intervient seulement si un contrat récent n'y figure pas encore, dans la fenêtre de 72 heures laissée à l'assureur pour le déclarer.`}},{"@type":`Question`,name:`Peut-on être verbalisé si le FVA n'est pas à jour alors que le contrat existe bel et bien ?`,acceptedAnswer:{"@type":`Answer`,text:`En principe non, à condition de présenter le Mémo Véhicule Assuré et de rester dans le délai légal de 72 heures. En cas de doute persistant de l'agent, le contrat souscrit reste vérifiable directement auprès de l'assureur.`}},{"@type":`Question`,name:`La carte internationale d'assurance est-elle utile en France ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, elle sert uniquement hors de France, dans les pays couverts par le contrat. En France, la preuve d'assurance passe par le FVA et, en attendant sa mise à jour, par le Mémo Véhicule Assuré.`}}]}],a={slug:`assurance-temporaire-attestation-immediate`,seo:{title:`Assurance temporaire : attestation immédiate expliquée`,description:`Dès le paiement : Mémo Véhicule Assuré et carte internationale d'assurance par email. Valeur en contrôle routier et délais réels du FVA expliqués.`,canonical:`https://assutempo.fr/articles/assurance-temporaire-attestation-immediate`,jsonLd:i},category:`Attestation`,readTime:`6 min`,updatedDate:`12 juillet 2026`,author:`Evidence Assurances`,headline:`Attestation immédiate : ce que vous recevez vraiment dès le paiement`,answerCapsule:{answer:`Dès le paiement validé, vous recevez par email le Mémo Véhicule Assuré et la carte internationale d'assurance : deux documents qui suffisent en contrôle routier. L'assureur inscrit ensuite le contrat au Fichier des Véhicules Assurés (FVA) sous 72 heures maximum, sans que cela retarde votre couverture.`,facts:[{anchor:`1er avril 2024`,text:`La carte verte papier a disparu ce jour-là : la preuve d'assurance repose désormais sur le Fichier des Véhicules Assurés (FVA), consultable par les forces de l'ordre à la plaque d'immatriculation (economie.gouv.fr).`},{anchor:`72 heures`,text:`Délai maximum dont dispose un assureur pour déclarer un nouveau contrat au FVA, géré par l'Agira depuis le 1er janvier 2019.`},{anchor:`3 750 €`,text:`Amende encourue devant le tribunal en cas de défaut d'assurance réel, avec immobilisation possible du véhicule (article L211-1 du Code des assurances, service-public.fr).`}],updated:`12 juillet 2026`},sections:[{type:`text`,heading:`Que recevez-vous exactement à la fin du paiement ?`,paragraphs:[`Deux documents, pas un seul. Le Mémo Véhicule Assuré d'abord : il reprend votre identité, l'immatriculation du véhicule, le nom de l'assureur et la période exacte de garantie, du jour et de l'heure de départ jusqu'à l'échéance choisie. La carte internationale d'assurance automobile ensuite, reconnue hors de France. Les deux arrivent par email en quelques minutes chez AssuTempo (assutempo.fr), sans relevé d'information ni questionnaire bonus-malus à remplir.`,`Rien à imprimer obligatoirement. Depuis 2024, ces documents se présentent au format numérique aussi bien que papier, et un contrôle routier se joue d'abord ailleurs, à la plaque d'immatriculation. C'est justement ce mécanisme qui mérite d'être détaillé, parce qu'il change ce qu'il faut avoir sous la main le jour où un agent vous arrête.`]},{type:`text`,heading:`Que faire si l'email de l'attestation n'arrive pas ?`,paragraphs:[`Ça arrive, rarement, mais ça arrive. Un fournisseur de messagerie trop strict range parfois le message dans les indésirables, surtout à la première souscription chez un nouvel assureur. Le réflexe simple : vérifier ce dossier avant d'appeler, l'attestation y atterrit neuf fois sur dix.`,`Si rien ne s'affiche après une dizaine de minutes, mieux vaut contacter directement l'équipe plutôt que de reprendre tout le parcours de souscription. Un duplicata du Mémo se renvoie en quelques instants, sans nouveau paiement, du moment que le contrat existe déjà.`]},{type:`alert`,heading:`Ce que dit le texte, chiffres à l'appui`,items:[`Carte verte papier supprimée depuis le 1er avril 2024, remplacée par le contrôle à la plaque.`,`Fichier des Véhicules Assurés (FVA) opérationnel depuis le 1er janvier 2019, consulté en temps réel par les forces de l'ordre.`,`L'assureur doit déclarer tout nouveau contrat au FVA sous 72 heures maximum (Agira, gestionnaire du fichier).`],note:`Le Mémo Véhicule Assuré comble cette fenêtre de 72 heures : c'est le document à présenter tant que le fichier n'est pas encore à jour (à vérifier sur service-public.fr).`},{type:`text`,heading:`Le Mémo Véhicule Assuré a-t-il une valeur légale en contrôle ?`,paragraphs:[`Une nuance utile ici. Le contrôle repose d'abord sur la consultation du FVA à la plaque, pas sur un papier que vous sortiriez de votre poche. Le Mémo n'est donc pas, à proprement parler, une preuve légale obligatoire à détenir. C'est un document pratique, remis par l'assureur, qui démontre votre bonne foi si le fichier n'a pas encore enregistré votre contrat, ou en cas de panne réseau côté agent.`,`Dans les faits, presque tous les agents demandent malgré tout un justificatif quand un doute existe. Garder le Mémo sur le téléphone évite une discussion inutile, même si techniquement, c'est la plaque interrogée au FVA qui tranche.`]},{type:`timeline`,heading:`Quel est le délai réel entre le paiement et une preuve complète ?`,steps:[{num:1,title:`Paiement validé`,body:`La garantie responsabilité civile prend effet à l'heure indiquée sur le contrat, en général celle du paiement. Rien n'attend le FVA pour démarrer.`},{num:2,title:`Email sous quelques minutes`,body:`Le Mémo Véhicule Assuré et la carte internationale d'assurance arrivent par email, à garder sur le téléphone ou à imprimer.`},{num:3,title:`FVA mis à jour sous 72 heures maximum`,body:`L'assureur dispose de ce délai légal pour déclarer le contrat. Un contrôle pendant cette fenêtre ne pose pas de problème si le Mémo est présenté.`},{num:4,title:`Contrôle routier`,body:`L'agent interroge la plaque au FVA. Si le contrat n'y figure pas encore, le Mémo suffit à prouver la souscription réelle.`}]},{type:`text`,heading:`Que couvre la carte internationale d'assurance à l'étranger ?`,paragraphs:[`Ce document remplace l'ancienne carte verte internationale, désormais imprimée sur fond blanc plutôt que vert. Il prouve votre couverture dans les pays où votre contrat s'applique, sans dépendre du FVA français, propre au territoire national. Chez AssuTempo (assutempo.fr), la couverture s'étend à 34 pays européens.`,`En dehors de l'Union européenne, certains postes-frontières demandent encore ce document au format papier. Autant l'imprimer avant un départ plutôt que de compter uniquement sur le téléphone. C'est aussi la différence essentielle avec le Mémo Véhicule Assuré : le Mémo prouve le contrat en France, la carte internationale le prouve à l'étranger. Les deux voyagent ensemble dans le même email, mais ne servent pas au même endroit.`],relatedLink:{text:`Voir les 34 pays couverts par l'assurance internationale`,href:`/assurance-internationale`}},{type:`checklist`,heading:`Quels documents avoir sous la main en cas de contrôle ?`,intro:`En France comme à l'étranger, ces pièces évitent toute discussion :`,items:[`Le Mémo Véhicule Assuré, sur smartphone ou imprimé`,`Un permis de conduire valide`,`La carte grise du véhicule, ou le certificat de cession si l'achat est tout récent`,`La carte internationale d'assurance, utile dès la sortie du territoire français`]},{type:`text`,heading:`Et si le véhicule vient d'être acheté, sans carte grise à votre nom ?`,paragraphs:[`Le principe reste le même : l'assureur délivre le Mémo Véhicule Assuré même si la carte grise n'est pas encore à votre nom, à partir du certificat de cession ou du numéro VIN. La transition administrative ne retarde jamais l'attestation.`],relatedLink:{text:`Voiture tout juste achetée, carte grise pas encore à votre nom ? Comment l'assurer`,href:`/articles/assurer-voiture-sans-carte-grise`}},{type:`text`,heading:`Que risque-t-on si aucune preuve d'assurance ne peut être présentée ?`,paragraphs:[`Rouler sans assurance reste un délit, sanctionné par une amende forfaitaire de 500 €, portée à 750 € avec la majoration au profit du Fonds de garantie. Devant le tribunal, l'amende peut grimper jusqu'à 3 750 €, avec suspension du permis et immobilisation du véhicule possibles (article L211-1 du Code des assurances). Ces chiffres méritent d'être vérifiés sur service-public.fr avant toute décision, les montants évoluant parfois.`,`Ces sanctions visent l'absence réelle de contrat, pas un simple décalage administratif du FVA. Un conducteur réellement assuré, Mémo à l'appui, n'a normalement rien à craindre pendant la fenêtre des 72 heures.`],relatedLink:{text:`Voiture immobilisée pour défaut d'assurance : comment la récupérer`,href:`/articles/voiture-immobilisee-defaut-assurance`}},{type:`callout`,title:`Le réflexe utile`,icon:`navigation`,text:`Depuis quelques mois, un conducteur peut vérifier lui-même en ligne si son véhicule figure bien au FVA, sans attendre un contrôle pour le découvrir. Un réflexe simple avant un long trajet, surtout juste après une souscription.`}],faqItems:[{q:`Le Mémo Véhicule Assuré remplace-t-il la carte verte ?`,a:`Oui. Depuis la suppression de la carte verte le 1er avril 2024, le Mémo Véhicule Assuré est le document remis par l'assureur à la souscription. Il ne remplace pas juridiquement le contrat, mais sert de preuve pratique tant que le Fichier des Véhicules Assurés (FVA) n'est pas encore à jour.`},{q:`Le FVA fait-il foi même sans présenter le Mémo ?`,a:`Oui, en priorité. Les forces de l'ordre consultent le FVA directement à la plaque d'immatriculation. Le Mémo intervient seulement si un contrat récent n'y figure pas encore, dans la fenêtre de 72 heures laissée à l'assureur pour le déclarer.`},{q:`Peut-on être verbalisé si le FVA n'est pas à jour alors que le contrat existe bel et bien ?`,a:`En principe non, à condition de présenter le Mémo Véhicule Assuré et de rester dans le délai légal de 72 heures. En cas de doute persistant de l'agent, le contrat souscrit reste vérifiable directement auprès de l'assureur.`},{q:`La carte internationale d'assurance est-elle utile en France ?`,a:`Non, elle sert uniquement hors de France, dans les pays couverts par le contrat. En France, la preuve d'assurance passe par le FVA et, en attendant sa mise à jour, par le Mémo Véhicule Assuré.`}]}}));function s(){return(0,c.jsx)(r,{data:a})}var c;e((()=>{n(),o(),c=t()}))();export{s as default};